<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>The Renewable Energy Cost Revolution, 2010–2024</title>
  <link href="https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=IBM+Plex+Sans:wght@300;400;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet">
  <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
  <script src="https://cdn.jsdelivr.net/npm/chartjs-plugin-annotation@3.0.1/dist/chartjs-plugin-annotation.min.js"></script>
  <style>
    :root {
      --bg: #f7f4ef;
      --surface: #ffffff;
      --surface-2: #f0ece3;
      --border: rgba(60, 50, 30, 0.12);
      --border-strong: rgba(60, 50, 30, 0.22);
      --text: #1a1510;
      --text-dim: #6b5f4a;
      --text-muted: #9c8e78;
      --solar: #d97706;
      --solar-dim: rgba(217, 119, 6, 0.15);
      --wind: #0369a1;
      --wind-dim: rgba(3, 105, 161, 0.15);
      --battery: #65a30d;
      --battery-dim: rgba(101, 163, 13, 0.15);
      --fossil-band: rgba(180, 60, 30, 0.10);
      --fossil-line: rgba(180, 60, 30, 0.45);
      --subsidy: #9f1239;
      --subsidy-dim: rgba(159, 18, 57, 0.12);
      --crossover: #b45309;
      --gold: #d4a73a;
      --font-body: 'IBM Plex Sans', system-ui, sans-serif;
      --font-serif: 'Instrument Serif', Georgia, serif;
      --font-mono: 'IBM Plex Mono', 'Courier New', monospace;
    }

    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    body {
      background: var(--bg);
      background-image:
        radial-gradient(ellipse 80% 50% at 20% 0%, rgba(212, 167, 58, 0.06) 0%, transparent 60%),
        radial-gradient(ellipse 60% 40% at 80% 100%, rgba(3, 105, 161, 0.05) 0%, transparent 60%);
      font-family: var(--font-body);
      color: var(--text);
      min-height: 100vh;
      padding: 0;
    }

    /* --- HEADER --- */
    .report-header {
      background: var(--text);
      color: var(--bg);
      padding: 56px 60px 44px;
      position: relative;
      overflow: hidden;
    }
    .report-header::after {
      content: '';
      position: absolute;
      bottom: 0; left: 0; right: 0;
      height: 3px;
      background: linear-gradient(90deg, var(--gold), var(--solar), var(--wind), var(--battery));
    }
    .report-header .kicker {
      font-family: var(--font-mono);
      font-size: 11px;
      letter-spacing: 0.15em;
      text-transform: uppercase;
      color: var(--gold);
      margin-bottom: 14px;
    }
