<script>
Chart.register(ChartAnnotation);

const years = [2010,2011,2012,2013,2014,2015,2016,2017,2018,2019,2020,2021,2022,2023,2024];

// LCOE data
const solar = [359,304,223,175,136,107,86,72,60,50,42,39,45,37,33];
const wind  = [95,89,82,78,72,64,56,52,48,44,41,38,42,37,35];
const batt  = [1100,980,860,750,620,510,395,310,245,187,150,132,139,119,102];

// Fossil band (interpolated for all 15 years)
// Biennial data: 2010,2012,2014,2016,2018,2020,2022,2024
const fossilYears  = [2010,2012,2014,2016,2018,2020,2022,2024];
const ffLow  = [55,50,48,42,44,45,55,50];
const ffHigh = [105,100,98,95,100,110,130,120];

// Interpolate fossil band to all years
function lerp(yrs, vals, targetYrs) {
  return targetYrs.map(ty => {
    const idx = yrs.findIndex(y => y >= ty);
    if (idx === 0) return vals[0];
    if (idx === -1) return vals[vals.length-1];
    const t = (ty - yrs[idx-1]) / (yrs[idx] - yrs[idx-1]);
    return vals[idx-1] + t * (vals[idx] - vals[idx-1]);
  });
}
const ffLowAll  = lerp(fossilYears, ffLow, years);
const ffHighAll = lerp(fossilYears, ffHigh, years);

// Capacity data
const solarCap = [40,70,100,137,177,227,303,402,512,627,760,942,1185,1550,1950];
const windCap  = [178,215,260,296,336,380,425,480,540,594,650,725,800,880,960];

// Subsidy data
const subsidyCons = [350,430,455,435,415,260,250,275,330,310,230,365,610,530,465];
const subsidyProd = [60,70,75,75,75,65,60,65,70,70,60,75,90,90,85];

const ROOT = getComputedStyle(document.documentElement);
function css(v) { return ROOT.getPropertyValue(v).trim(); }

const clrSolar   = '#d97706';
const clrWind    = '#0369a1';
const clrBattery = '#65a30d';
const clrFossil  = 'rgba(180, 60, 30, 0.18)';
const clrCrossover = '#b45309';
const clrSubsidy = '#9f1239';
const clrSubProd = '#fb7185';
const clrText    = '#1a1510';
const clrDim     = '#9c8e78';
const clrBorder  = 'rgba(60,50,30,0.12)';
const clrBg      = '#ffffff';

const fontMono = "'IBM Plex Mono', monospace";
const fontBody = "'IBM Plex Sans', sans-serif";

Chart.defaults.font.family = fontBody;
Chart.defaults.color = clrDim;

// ─── CHART 1: LCOE ──────────────────────────────────────────────────────────
const ctx1 = document.getElementById('chart-lcoe').getContext('2d');

// Build fossil band as fill-between using two datasets
new Chart(ctx1, {
  data: {
    labels: years,
    datasets: [
      // Fossil band fill
      {
        type: 'line',
        label: 'Fossil Low',
        data: ffLowAll,
        borderColor: 'transparent',
        backgroundColor: 'transparent',
        fill: false,
        pointRadius: 0,
        tension: 0.35,
        order: 5
      },
      {
        type: 'line',
        label: 'Fossil High',
        data: ffHighAll,
        borderColor: 'rgba(180,60,30,0.3)',
        borderWidth: 1,
        borderDash: [4,3],
        backgroundColor: 'rgba(180,60,30,0.10)',
        fill: '-1',
        pointRadius: 0,
        tension: 0.35,
        order: 4
      },
      // Solar PV
      {
        type: 'line',
        label: 'Solar PV',
        data: solar,
        borderColor: clrSolar,
        backgroundColor: 'rgba(217,119,6,0.08)',
        borderWidth: 2.5,
        fill: false,
        pointRadius: [4,3,3,3,3,3,3,3,3,3,3,3,3,3,4],
        pointBackgroundColor: clrSolar,
        tension: 0.3,
        order: 1
      },
      // Wind
      {
        type: 'line',
        label: 'Onshore Wind',
        data: wind,
        borderColor: clrWind,
        backgroundColor: 'rgba(3,105,161,0.08)',
        borderWidth: 2.5,
        fill: false,
        pointRadius: [4,3,3,3,3,3,3,3,3,3,3,3,3,3,4],
        pointBackgroundColor: clrWind,
        tension: 0.3,
        order: 2
      },
      // Battery (separate Y axis)
      {
        type: 'line',
        label: 'Battery Storage',
        data: batt,
        borderColor: clrBattery,
        backgroundColor: 'rgba(101,163,13,0.05)',
        borderWidth: 2,
        borderDash: [6,3],
        fill: false,
        pointRadius: [4,3,3,3,3,3,3,3,3,3,3,3,3,3,4],
        pointBackgroundColor: clrBattery,
        tension: 0.3,
        yAxisID: 'yBatt',
        order: 3
      }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    interaction: { mode: 'index', intersect: false },
    plugins: {
      legend: { display: false },
      tooltip: {
        backgroundColor: 'rgba(26,21,16,0.92)',
        titleColor: '#f0ebe0',
        bodyColor: '#a89e88',
        borderColor: 'rgba(212,167,58,0.3)',
        borderWidth: 1,
        padding: 12,
        callbacks: {
          label: ctx => `${ctx.dataset.label}: $${ctx.parsed.y} /MWh`
        }
      },
      annotation: {
        annotations: {
          // Crossover region - wind crossed fossil low around 2017
          windCrossover: {
            type: 'line',
            xMin: '2017', xMax: '2017',
            borderColor: clrWind,
            borderWidth: 1.5,
            borderDash: [5,4],
            label: {
              display: true,
              content: 'Wind < Fossil Low ~2017',
              position: 'start',
              backgroundColor: 'rgba(3,105,161,0.12)',
              color: clrWind,
              font: { family: fontMono, size: 10, weight: '500' },
              padding: { x: 7, y: 4 },
              borderRadius: 2,
              yAdjust: 20
            }
          },
          // Solar crossed fossil low around 2019
          solarCrossover: {
            type: 'line',
            xMin: '2019', xMax: '2019',
            borderColor: clrSolar,
            borderWidth: 1.5,
            borderDash: [5,4],
            label: {
              display: true,
              content: 'Solar < Fossil Low ~2019',
              position: 'start',
              backgroundColor: 'rgba(217,119,6,0.12)',
              color: clrSolar,
              font: { family: fontMono, size: 10, weight: '500' },
              padding: { x: 7, y: 4 },
              borderRadius: 2,
              yAdjust: 55
            }
          },
          // 2022 energy crisis marker
          crisisBox: {
            type: 'box',
            xMin: '2021.5', xMax: '2022.5',
            yMin: 0, yMax: 150,
            backgroundColor: 'rgba(180,60,30,0.04)',
            borderColor: 'rgba(180,60,30,0.15)',
            borderWidth: 1,
            label: {
              display: true,
              content: '2022 energy crisis',
              position: { x: 'center', y: 'start' },
              color: 'rgba(180,60,30,0.65)',
              font: { family: fontMono, size: 9 },
              padding: { x: 5, y: 3 }
            }
          }
        }
      }
    },
    scales: {
      x: {
        grid: { color: clrBorder, lineWidth: 1 },
        ticks: {
          font: { family: fontMono, size: 11 },
          color: clrDim,
          maxRotation: 0
        },
        border: { display: false }
      },
      y: {
        title: {
          display: true,
          text: 'LCOE — USD/MWh (2023 real)',
          font: { family: fontMono, size: 10 },
          color: clrDim,
          padding: { bottom: 8 }
        },
        grid: { color: clrBorder, lineWidth: 1 },
        ticks: {
          font: { family: fontMono, size: 11 },
          color: clrDim,
          callback: v => '$' + v
        },
        min: 0, max: 160,
        border: { display: false }
      },
      yBatt: {
        position: 'right',
        title: {
          display: true,
          text: 'Battery LCOE — USD/MWh',
          font: { family: fontMono, size: 10 },
          color: clrBattery,
          padding: { bottom: 8 }
        },
        grid: { display: false },
        ticks: {
          font: { family: fontMono, size: 11 },
          color: clrBattery,
          callback: v => '$' + v
        },
        min: 0, max: 1250,
        border: { display: false }
      }
    }
  }
});

// ─── CHART 2: CAPACITY ───────────────────────────────────────────────────────
const ctx2 = document.getElementById('chart-capacity').getContext('2d');
new Chart(ctx2, {
  type: 'line',
  data: {
    labels: years,
    datasets: [
      {
        label: 'Solar PV',
        data: solarCap,
        borderColor: clrSolar,
        backgroundColor: 'rgba(217,119,6,0.12)',
        borderWidth: 2.5,
        fill: true,
        pointRadius: [4,3,3,3,3,3,3,3,4,3,3,3,3,3,5],
        pointBackgroundColor: clrSolar,
        tension: 0.3
      },
      {
        label: 'Onshore Wind',
        data: windCap,
